+const NOOP = () => {};
+
+export interface FormData {
+  clusteringRadius: number;
+  globalOpacity: number;
+  mapboxColor: string;
+  mapboxStyle: string;
+  pandasAggfunc: string;
+  pointRadius: number | string;
+  pointRadiusUnit: string;
+  renderWhileDragging: boolean;
+}
+
+interface ViewportChangeParams {
+  latitude: number;
+  longitude: number;
+  zoom: number;
+}
+
+interface ClusterOptions {
+  maxZoom: number;
+  radius: number;
+  initial?: () => {
+    sum: number;
+    squaredSum: number;
+    min: number;
+    max: number;
+  };
+  map?: (prop: { metric: number }) => {
+    sum: number;
+    squaredSum: number;
+    min: number;
+    max: number;
+  };
+  reduce?: (
+    accu: {
+      sum: number;
+      squaredSum: number;
+      min: number;
+      max: number;
+    },
+    prop: {
+      sum: number;
+      squaredSum: number;
+      min: number;
+      max: number;
+    },
+  ) => void;
+}
+
+interface TransformedProps {
+  width?: number;
+  height?: number;
+  aggregatorName?: string;
+  bounds?: [[number, number], [number, number]];
+  clusterer?: Supercluster;
+  globalOpacity?: number;
+  hasCustomMetric?: boolean;
+  mapboxApiKey?: string;
